    SaveData.TheoBridge.Gelatek = options

    local previousOptionsSchema = tonumber(options.SchemaVersion) or 0
    local CURRENT_OPTIONS_SCHEMA = 22
    local defaults = {
        -- Match Gelatek's original behavior: its controller can animate even
