    options.CFrameFirst = nil
    options.PhysicsAccessoryHandles = nil
    options.PhysicalRecoveryDistance = math.clamp(
        tonumber(options.PhysicalRecoveryDistance) or 0, 0, 50)
    if options.PhysicalRecoveryDistance ~= options.PhysicalRecoveryDistance then options.PhysicalRecoveryDistance = 0 end
    options.DirectPositionCorrection = options.DirectPositionCorrection == true
    options.DisableDirectionalWalking = options.DisableDirectionalWalking == true
    options.ShowMeHowILook = options.ShowMeHowILook == true

    -- Schema 14 shipped accessory detachment as the default. There is no way
    -- to distinguish that inherited default from an intentional selection, so
    -- migrate once to the safe policy. The explicit advanced toggle can still
    -- be enabled again after this migration.
    if previousOptionsSchema < 15 then
        options.BreakAccessoryWelds = false
