--!optimize 2

cloneref = cloneref or function(o) return o end

local Players = cloneref(game:GetService("Players"))
local RunService = cloneref(game:GetService("RunService"))

local Player = Players.LocalPlayer

local modules = {}
local function AddModule(m)
	table.insert(modules, m)
end

local function SetC0C1Joint(j, c0, c1, scale)
	local t = c0 * c1:Inverse()
	t += t.Position * (scale - 1)
	t = j.C0:Inverse() * t * j.C1
	j.Transform = t
end

AddModule(function()
	local m = {}
	m.ModuleType = "DANCE"
	m.Name = "Ragdoll"
	m.Description = "faint, or die\nAnimation-less, physics based, real and istic ragdoll."
	m.InternalName = "RAGDOLL"
