	local animator = nil
	local start = 0
	m.Init = function(figure: Model)
		start = os.clock()
		SetOverrideDanceMusic("rbxassetid://9039445224", "8 Bitty Kitty Underscore", 1)
		animator = AnimLib.Animator.new()
