				MeleeEffect(Attack(rootu.CFrame * CFrame.new(0, 0, -3 * scale), Vector3.new(6, 5, 5) * scale))
				task.wait(seconds / 2 + 0.2)
				if not rootu:IsDescendantOf(workspace) then
					return
				end
			end
			animationOverride = nil
			attacking = false
		end)
	end
