		sword6 = function(timingsine, rt, nt, rst, lst, rht, lht)
			rt = RC0 * CFrame.Angles(math.rad(20), 0, 0)
			nt = NC0 * CFrame.Angles(math.rad(-10), math.rad(-5), 0)
			rst = CFrame.new(1, 0.2, -0.5) * CFrame.Angles(math.rad(10), 0, math.rad(-50))
